// The showcase "wish worlds" (docs/specs/generated-worlds-spec.md section 0): worlds a wish made, painted offline with the same brief and image code the live route uses, shipped as assets and pick-able in the Create
// card. Each is an ordinary level of its BASE theme (the base world's own props and hiding spots, so it plays exactly like it: a generated look never changes how a world plays) wearing its own sky, fog and ground
// colours for day and night and its own backdrop art. The data (palettes, art URLs) is generated by scripts/bake-wish-worlds.ts into wishWorlds.data.ts.
import { LEVELS, type LevelDef } from "./catalog";
import { generatedBackdrops, registerBackdrop, type GeneratedArt } from "./backdrop";
import { WISH_DATA, type WishData } from "./wishWorlds.data";

/** What a card in the Create sheet shows. */
export interface WishCard { id: string; name: string }

export const wishCards = (): WishCard[] => WISH_DATA.map((w) => ({ id: w.id, name: w.look.name }));
export const findWish = (id: string): WishData | null => WISH_DATA.find((w) => w.id === id) ?? null;

/** A fresh level for a wish world: the base theme's level (props, hiding spots) with the world's name and look. `id` is "kid-world", the id Create's level always has. Null for an unknown wish. */
export function wishLevel(id: string): LevelDef | null {
  const w = findWish(id);
  if (!w) return null;
  const base = LEVELS.find((l) => l.id === w.base);
  if (!base) return null;
  const copy = JSON.parse(JSON.stringify({ props: base.props, spots: base.spots })) as Pick<LevelDef, "props" | "spots">;
  return { format: "toyventor.level/1", id: "kid-world", name: w.look.name, theme: w.base, props: copy.props, spots: copy.spots, look: JSON.parse(JSON.stringify(w.look)) };
}

/** Give the world its bundled art (an indoor world has none). Safe to call again. */
export function registerWishArt(id: string): boolean {
  const w = findWish(id);
  if (!w) return false;
  if (w.art) registerBackdrop(w.look.id, generatedBackdrops(w.art satisfies GeneratedArt));
  return true;
}

/** Register the art of the showcase world a stored look belongs to (by look id): a saved or shared level that carries a showcase look gets its art back with no device storage. */
export function registerWishArtForLook(lookId: string): boolean {
  const w = WISH_DATA.find((x) => x.look.id === lookId);
  return w ? registerWishArt(w.id) : false;
}
